package com.ftk.tpip.control.application.integration;

import com.fasterxml.jackson.databind.JsonNode;import com.ftk.tpip.integration.domain.exception.PolicyTypeAlreadyExistsException;import com.ftk.tpip.integration.domain.model.*;import com.ftk.tpip.integration.domain.repository.PolicyTypeRepository;import com.ftk.tpip.shared.*;import java.net.URI;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PolicyTypeApplicationService{private final PolicyTypeRepository repo;private final PolicyContentCanonicalizer canonicalizer;public PolicyTypeApplicationService(PolicyTypeRepository repo,PolicyContentCanonicalizer c){this.repo=repo;this.canonicalizer=c;}
@Transactional public PolicyTypeDefinition register(String code,String version,PolicyImplementationKind kind,Set<PolicyMountStage> stages,JsonNode schema,String compatibility,PolicySecurityClassification security,boolean deterministic,boolean sideEffect,PolicyIdempotencyRequirement idempotency,String implementationRef,String checksum,String actor){AssetCode c=AssetCode.of(code);SemanticVersion v=SemanticVersion.parse(version);if(repo.findByReference(c.value(),v.toString()).isPresent())throw new PolicyTypeAlreadyExistsException(c+"@"+v);String ref=validateRef(kind,implementationRef);return repo.create(PolicyTypeDefinition.create(c,v,kind,stages,canonicalizer.schema(schema),compatibility,security,deterministic,sideEffect,idempotency,ref,checksum),actor(actor));}
@Transactional(readOnly=true)public PolicyTypeDefinition get(long id){return repo.findById(id).orElseThrow(()->new PolicyTypeNotFoundException(id));}@Transactional(readOnly=true)public List<PolicyTypeDefinition> list(boolean activeOnly){return repo.findAll(activeOnly);}@Transactional public PolicyTypeDefinition status(long id,PolicyTypeStatus status,String actor){get(id);return repo.setStatus(id,status,actor(actor));}
private static String validateRef(PolicyImplementationKind kind,String value){if(value==null||value.isBlank()){if(kind==PolicyImplementationKind.PLUGIN)throw new IllegalArgumentException("PLUGIN requires implementationRef");return null;}URI uri=URI.create(value.trim());String expected=kind==PolicyImplementationKind.BUILTIN?"builtin":"artifact";if(!expected.equals(uri.getScheme())||uri.getQuery()!=null||uri.getFragment()!=null)throw new IllegalArgumentException("implementationRef must use "+expected+": scheme without query or fragment");return value.trim();}private static String actor(String a){if(a==null||a.isBlank()||a.trim().length()>100)throw new IllegalArgumentException("X-Operator is blank or too long");return a.trim();}}
